// Recibe {evento, pedido, usuario, destinatarios:[{whatsapp,nombre}]} y arma
// un item por destinatario con el texto del mensaje.
const first = $input.first().json;
const headers = first.headers || {};
const WEBHOOK_KEY = 'PEGAR_WEBHOOK_KEY';
if ((headers['x-app-key'] || '') !== WEBHOOK_KEY) { return []; }
const body = first.body || {};
const p = body.pedido || {};
const dest = Array.isArray(body.destinatarios) ? body.destinatarios : [];

const TEXTOS = {
  pedido_nuevo: `\u{1F4CB} *Pedido nuevo ${p.numero || ''}* (${p.prioridad === 'urgente' ? '\u{1F534} URGENTE' : 'normal'})\nObra: ${p.obraNombre}\nRubro: ${p.rubro}\nPidi\u00f3: ${body.usuario}`,
  pedido_proveedor: `\u{1F6D2} Tu pedido *${p.numero}* (${p.obraNombre}) ya fue pedido al proveedor.\nEntrega estimada: ${p.fechaEstimada || 's/d'}`,
  entrega_parcial: `\u{1F4E6} Recepci\u00f3n PARCIAL registrada en *${p.numero}* (${p.obraNombre}) por ${body.usuario}.`,
  entregado: `\u2705 Pedido *${p.numero}* (${p.obraNombre}) recibido COMPLETO. Se cierra.`,
  cancelado: `\u274C Pedido *${p.numero}* (${p.obraNombre}) CANCELADO por ${body.usuario}.`,
  reclamo: `\u{1F6A8} *RECLAMO* de ${body.usuario} en *${p.numero}* (${p.obraNombre}) \u2014 sigue sin llegar.`
};
const texto = TEXTOS[body.evento] || `Novedad en pedido ${p.numero}: ${body.evento}`;

const out = [];
for (const d of dest) {
  const num = String(d.whatsapp || '').replace(/[^0-9]/g, '');
  if (!num) continue;
  out.push({ json: { number: num, text: texto + '\n\nhttps://skyterrasl.github.io/pedidos-obra/' } });
}
return out;
